def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def generate_k(limit):
    ks = set()
    primes = [i for i in range(2, limit) if is_prime(i)]
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            k = primes[i] * primes[j]
            if k <= limit:
                ks.add(k)
    return sorted(list(ks))

# We need to generate enough to get 20 elements. Let's estimate a limit.
# The 20th element is 69. Let's check up to 100.
all_k = generate_k(100)
